      "threatens_conclusions": true,
      "findings": [
        {
          "title": "Immortal time bias and lack of exposure duration threshold",
          "mechanism": "Patients who initiated therapy shortly before cutoff or received a single script are counted as fully exposed, while person-time prior to the first prescription is misattributed or unmodeled.",
          "evidence": [
            "Any prior or current use counted as exposed",
            "No minimum therapy duration required",
            "Dose not accounted for; no washout period applied",
            "Time-to-event analysis not performed; static 2x2 contingency tables used"
